+export interface Record {
+  path: string;
+  startLine: number;
+  endLine: number;
+  data: unknown;
+}
+
+export const project = (records: readonly Record[]): string => {
+  return records.map(r => `${r.path}:${r.startLine}-${r.endLine}`).join('\n');
+};
